(function(){try{var e=typeof window<`u`?window:typeof global<`u`?global:typeof globalThis<`u`?globalThis:typeof self<`u`?self:{};e.SENTRY_RELEASE={id:`f99fcf9f0a844cc9bd13fdc8e5782b84`};var t=new e.Error().stack;t&&(e._sentryDebugIds=e._sentryDebugIds||{},e._sentryDebugIds[t]=`b6a15e12-901d-4ad4-8a7f-05e7c3a96dde`,e._sentryDebugIdIdentifier=`sentry-dbid-b6a15e12-901d-4ad4-8a7f-05e7c3a96dde`)}catch{}})();import{r as e}from"../chunks/COtFpfH5.js";import{St as t,bt as n}from"../chunks/F_ixKBiO.js";import{t as r}from"../chunks/BqPQayrc.js";import"../chunks/B1sc9Zdx.js";import"../chunks/Bb2deiU3.js";var i=()=>({title:`Data Processing Addendum | Modal`,ogTitle:`Data Processing Addendum`}),a=e({load:()=>o,prerender:()=>!1}),o=i?r(i):void 0,s=t(`<section class="max-w-(--breakpoint-xl) mx-auto px-4"><div class="prose prose-sm sm:prose-base mx-auto py-16"><h1>Modal Labs, Inc. Data Processing Addendum</h1> <p><em>Effective October 31, 2025.</em></p> <p>This Data Processing Addendum (the "<strong>DPA</strong>") is incorporated
      by reference into the agreement between Modal Labs, Inc. (<strong>“Modal”</strong>) and Customer (the "<strong>Agreement</strong>") regarding the Services
      described in the Agreement. This DPA is supplemental to the Agreement and
      sets out the terms that apply when Personal Data (defined below) is
      processed by Modal under the Agreement. Capitalized terms have the
      meanings provided in the Agreement except as provided here.</p> <p>IT IS AGREED AS FOLLOWS:</p> <ol><li><p><strong>Definitions and Interpretation</strong></p></li> <p>Unless otherwise defined herein, capitalized terms and expressions used
        in this DPA shall have the following meaning:</p> <p>"<strong>Applicable Privacy Law(s)</strong>" means all worldwide data
        protection and privacy laws and regulations applicable to the Personal
        Data in question, including, where applicable:</p> <ul style="list-style-type:none"><p>"<strong>EU Data Protection Law</strong>”: Regulation 2016/679 of the
          European Parliament and of the Council on the protection of natural
          persons with regard to the Processing of Personal Data and on the free
          movement of such data (General Data Protection Regulation) (<strong>“GDPR”</strong>) and the EU e-Privacy Directive (Directive 2002/58/EC), each as
          implemented and transposed into local law by any EU member states.</p> <p>"<strong>Swiss DPA”:</strong> the Swiss Federal Act on Data Protection
          1992 (including as amended or superseded).</p> <p>"<strong>UK Data Protection Law”:</strong> the UK Data Protection Act and
          GDPR as incorporated into UK law by the Data Protection Act 2018 and amended
          by the Data Protection, Privacy and Electronic Communications (Amendments
          etc) (EU Exit) Regulations 2019 (each as amended, superseded, or replaced).</p> <p>"<strong>US Data Protection Law”:</strong> all applicable
          comprehensive state Applicable Privacy Laws and regulations in each
          case as may be amended or superseded from time to time, including the
          California Privacy Rights Act ("<strong>CPRA</strong>"); Colorado
          Privacy Act; Connecticut Personal Data Privacy and Online Monitoring
          Act; Delaware Personal Data Privacy Act; Indiana Consumer Data
          Protection Act; Iowa Consumer Data Protection Act; Montana Consumer
          Data Privacy Act; Oregon Consumer Privacy Act; Tennessee Information
          Protection Act; Texas Data Privacy and Security Act; Utah Consumer
          Privacy Act; Virginia Consumer Data Protection Act.</p></ul> <p>"<strong>Customer Personal Data</strong>" means any Personal Data
        Processed by a Subprocessor on behalf of Customer pursuant to or in
        connection with the Agreement;</p> <p>"<strong>Data Breach</strong>" means a breach of security leading to the
        accidental or unlawful destruction, loss, alteration, unauthorized
        disclosure of, or access to, Customer Personal Data.</p> <p>"<strong>Controller</strong>", "<strong>Data Subject</strong>", "<strong>Process</strong>" (whether or not capitalized), "<strong>Processor</strong>”, and "<strong>Subprocessor</strong>" have the meanings ascribed to them by GDPR and include equivalent
        terms in California Data Protection Law, in each case as applicable to
        the Services.</p> <p>"<strong>EEA</strong>" means the European Economic Area;</p> <p>"<strong>Standard Contractual Clauses</strong>" or "<strong>SCCs</strong>" means: (a) where EU Data Protection Law or the Swiss DPA applies, the
        contractual clauses annexed to the European Commission’s Implementing
        Decision 2021/914 of 4 June 2021 on standard contractual clauses for the
        transfer of Personal Data to third countries pursuant to Regulation (EU)
        2016/679 of the European Parliament and of the Council ("<strong>EU SCCs</strong>"); and (b) where UK Data Protection Law applies, standard data
        protection clauses adopted pursuant to or permitted under UK Data
        Protection Law (<strong>“UK SCCs”</strong>).</p> <li><p><strong>Processing of Customer Personal Data</strong></p></li> <ol><li><p><strong>Purpose Limitation.</strong> Modal will not Process Customer
            Personal Data for any purpose other than for the specific purposes set
            forth in this DPA, unless obligated to do otherwise by Applicable Privacy
            Law. In such case, Modal will inform Customer of that legal requirement
            before the Processing unless legally prohibited from doing so. Modal
            shall only Process Customer Personal Data for the following purposes:
            (a) Processing as reasonably required to provide the Service and perform
            Modal’s obligations under the Agreement and this DPA, and as otherwise
            agreed by the Parties; (b) Processing initiated by Customer and its users
            in their use of the Service; (c) Processing to comply with other reasonable
            instructions provided by Customer (e.g., via email or support tickets)
            that are consistent with the terms of the Agreement and Applicable Privacy
            Laws; and (d) as otherwise required by Applicable Privacy Laws. Further
            details regarding Modal’s Processing operations are set forth in Schedule
            1.</p></li> <li><p><strong>Lawful Instructions.</strong> Customer shall, in its use of the
            Service, Process Customer Personal Data in accordance with the requirements
            of Applicable Privacy Law. Customer shall have sole responsibility for
            the accuracy, quality, and legality of Customer Personal Data and the
            means by which Customer acquired Customer Personal Data. Customer will
            not instruct Modal to Process Personal Data in violation of Applicable
            Privacy Law. Modal has no obligation to monitor the compliance of Customer’s
            use of the Service with Applicable Privacy Law, though Modal will immediately
            inform Customer if, in Modal’s opinion, an instruction from Customer
            infringes Applicable Privacy Law.</p></li> <li><p><strong>CPRA Requirements.</strong> With respect to Customer Personal
            Data to which the CPRA applies (capitalized terms used in this section
            having the meanings provided in CPRA):</p></li> <ol type="a"><li><p>Modal shall act as a Service Provider to Customer and shall
              collect, access, maintain, use, process, and transfer Customer
              Personal Data solely for the purpose of performing Modal’s
              obligations under this Agreement for or on behalf of Customer and
              for no commercial purpose other than the performance of such
              obligations.</p></li> <li><p>Modal shall not Sell or Share (as defined in CPRA), disclose,
              release, transfer, make available or otherwise communicate any
              Customer Personal Data to another business or third party without
              Customer’s prior written consent unless and to the extent that
              such disclosure is made to a Subcontractor for a business purpose,
              subject to Section 5.1(a) below. Notwithstanding the foregoing,
              nothing in this DPA shall restrict Modal’s ability to disclose
              Customer Personal Data to comply with applicable laws; provided
              that if such disclosure is required, Modal will promptly notify
              Customer of the request for disclosure unless such notification is
              prohibited by applicable law or a legally binding order.</p></li></ol></ol> <li><p><strong>Processor Personnel</strong></p></li> <p>Processor shall take reasonable steps to ensure the reliability of any
        employee, agent or contractor of any Subprocessor who may have access to
        the Customer Personal Data, ensuring in each case that access is
        strictly limited to those individuals who need to know / access the
        relevant Customer Personal Data, as strictly necessary for the purposes
        of the Agreement, and to comply with Applicable Laws in the context of
        that individual's duties to the Subprocessor, ensuring that all such
        individuals are subject to confidentiality undertakings or professional
        or statutory obligations of confidentiality.</p> <li><p><strong>Security</strong></p></li> <ol><li><p>Taking into account the state of the art, the costs of
            implementation and the nature, scope, context and purposes of
            Processing as well as the risk of varying likelihood and severity
            for the rights and freedoms of natural persons, Processor shall in
            relation to the Customer Personal Data implement appropriate
            technical and organizational measures, described on Schedule 2, to
            ensure a level of security appropriate to that risk, including, as
            appropriate, the measures referred to in Article 32(1) of the GDPR.</p></li> <li><p>In assessing the appropriate level of security, Processor shall take
            account, in particular, the risks that are presented by Processing
            from a Personal Data Breach perspective.</p></li></ol> <li><p><strong>Subprocessing</strong></p></li> <ol><li><p>Customer hereby consents to Modal’s appointment of Subprocessors of
            Personal Data under this Agreement. Modal’s current Subprocessors
            are listed on Schedule 3 hereto. Modal confirms that it:</p> <ol type="a"><li>has entered (or, for future appointments, will enter) into a
              written agreement with each Subprocessor incorporating terms which
              are at least as protective of Personal Data provided by Customer
              as those set out in this DPA; and</li> <li>will update the website above with any intended changes concerning
              the addition or replacement of Subprocessors, thereby giving
              Customer the opportunity to object to such changes. That website
              includes a self-enrollment system where Customer can add an email
              address to receive notices of Subprocessor changes. Customer’s
              sole recourse if it objects to a Subprocessor will be to terminate
              Customer’s subscription to the Service.</li></ol></li> <li><p><strong>Emergency Replacement.</strong> Modal may replace a Subprocessor
            if the need for the change is urgent and necessary to provide the Service.
            In such instance, Modal shall notify Customer of the replacement as soon
            as reasonably practicable, and Customer shall retain the right to object
            to the replacement Subprocessor as described above.</p></li></ol> <li><p><strong>Data Subject Rights</strong></p></li> <ol><li><p>Taking into account the nature of the Processing, Processor shall
            assist the Customer by implementing appropriate technical and
            organisational measures, insofar as this is possible, for the
            fulfilment of the Customer obligations, as reasonably understood by
            Customer, to respond to requests to exercise Data Subject rights
            under the Applicable Privacy Laws.</p></li> <li><p>Processor shall:</p> <ol type="a"><li>promptly notify Customer if it receives a request from a Data
              Subject under any Applicable Privacy Laws in respect of Customer
              Personal Data; and</li> <li>ensure that it does not respond to that request except on the
              documented instructions of Customer or as required by Applicable
              Privacy Laws to which the Processor is subject, in which case
              Processor shall to the extent permitted by Applicable Privacy Laws
              inform Customer of that legal requirement before the Processor
              responds to the request.</li></ol></li></ol> <li><p><strong>Personal Data Breach</strong></p></li> <ol><li><p>Processor shall notify Customer without undue delay upon Processor
            becoming aware of a Personal Data Breach affecting Customer Personal
            Data, providing Customer with sufficient information to allow the
            Customer to meet any obligations to report or inform Data Subjects
            of the Personal Data Breach under the Applicable Privacy Laws.</p></li> <li><p>Processor shall co-operate with the Customer and take commercially
            reasonable steps as are directed by Customer to assist in the
            investigation, mitigation, and remediation of each such Personal
            Data Breach.</p></li></ol> <li><p><strong>Data Protection Impact Assessment and Prior Consultation</strong></p></li> <p>Processor shall provide reasonable assistance to the Customer with any
        data protection impact assessments, and prior consultations with
        Supervising Authorities or other competent data privacy authorities,
        which Customer reasonably considers to be required by article 35 or 36
        of the GDPR or equivalent provisions of any other Data Protection Law,
        in each case solely in relation to Processing of Customer Personal Data
        by, and taking into account the nature of the Processing and information
        available to, the Subprocessors.</p> <li><p><strong>Deletion or return of Customer Personal Data</strong></p></li> <ol><li><p>On termination of the Agreement, Modal will delete and procure the
            deletion of all copies of Customer Personal Data as described in the
            MSA.</p></li></ol> <li><p><strong>Audit rights</strong></p></li> <ol><li><p>Customer may request an on-site audit of Processor’s applicable
            controls related to the processing activities under this DPA when:
            (a) the information provided under the information provided by
            Processor is not sufficient to demonstrate compliance with the
            obligations set out in this DPA or (b) required by Applicable
            Privacy Laws or Customer’s competent supervisory authority. Upon
            Customer’s written request, at reasonable intervals, and subject to
            the confidentiality obligations set forth in the Agreement,
            Processor shall make available to Customer information regarding
            Processor’s compliance with the obligations set forth in this DPA in
            the form of a copy of Processor’s then most recent third-party
            audits or certifications, if any.</p></li></ol> <li><p><strong>Cross Border Transfers</strong></p></li> <ol><li><p><strong>Consent.</strong> Modal may not transfer Personal Data to, or
            process such data in, a location outside of the European Economic Area
            or the UK without Customer’s prior written consent, except in compliance
            with Section 10.2 below (in each case a “Transfer”).</p></li> <li><p><strong>Compliant Transfer Mechanisms.</strong> Without prejudice to
            the foregoing, Customer consents to Transfers where Modal has implemented
            a Transfer solution compliant with GDPR and UK GDPR, which for example
            may include: (a) an adequacy decision by applicable authorities; (b)
            the Standard Contractual Clauses as incorporated herein pursuant to Appendix
            1; (c) another appropriate safeguard pursuant to Article 46 of GDPR or
            UK GDPR equivalent; or (d) a derogation pursuant to Article 49 of GDPR
            or UK GDPR equivalent.</p></li></ol> <li><p><strong>General Terms</strong></p></li> <ol><li><p>This DPA is part of the Agreement and is governed by its terms and
            conditions including limitations of liability.</p></li> <li><p>This DPA will be governed by and construed in accordance with the
            governing law and jurisdiction provisions in the Agreement unless
            required otherwise by GDPR, in which case this DPA will be governed
            by the laws of Sweden.</p></li> <li><p>In the event of inconsistencies between this DPA and the SCCs, this
            DPA shall prevail to the extent this DPA offers a stronger privacy
            protection for data subjects. Otherwise the SCCs shall apply.</p></li></ol></ol> <h2>APPENDIX 1: APPLICABLE STANDARD CONTRACTUAL CLAUSES AND SUPPLEMENTAL TERMS</h2> <ol><li><p><strong>Incorporation of Standard Contractual Clauses</strong></p></li> <p>The parties agree that the Standard Contractual Clauses are hereby
        incorporated by reference into this DPA as follows:</p> <ol><li><p>Module 1: Transfer controller to controller, Clauses 1 to 6, 8 and
            10 to 18 apply where Modal Processes Personal Data as a Controller,
            Modal and its relevant Affiliates are located in non-adequacy
            approved third countries, and Customer and its relevant Affiliates
            are established in the EEA.</p></li> <li><p>Module 2: Transfer controller to processor, Clauses 1 to 6 and 8 to
            18 apply where Modal Processes Personal Data as a Processor, Modal
            and its relevant Sub-Processor Affiliates are located in
            non-adequacy approved third countries, and Customer and its relevant
            Affiliates are established in the EEA.</p></li> <li><p>Module 3: Transfer processor to processor, Clauses 1 to 6 and 8 to
            18 apply where Modal Processes Personal Data as a Processor, Modal
            and its relevant Sub-Processor Affiliates are located in
            non-adequacy approved third countries, and Customer and its relevant
            Affiliates are established in the EEA.</p></li></ol> <li><p><strong>Standard Contractual Clause Optional Provisions</strong></p></li> <p>Where the Standard Contractual Clauses identify optional provisions (or
        provisions with multiple options) the following shall apply in the
        following manner:</p> <ol><li>Clause 7 (Docking Clause) is omitted;</li> <li>In Clause 9(a) (Use of sub-processors) – Option 2 shall apply and the
          parties shall follow the process and timing agreed in the DPA to
          appoint sub-processors;</li> <li>In Clause 11(a) (Redress) – the Optional provision shall NOT apply;</li> <li>In Clause 16(b) (Suspension of transfers) if Modal is the data
          exporter it will suspend transfers of personal data only as required
          by law and will notify Customer as promptly as possible (before
          suspension if possible) so that Customer may remedy the condition
          requiring suspension;</li> <li>In Clause 17 (Governing Law) – the laws of Sweden shall govern; and</li> <li>In Clause 18 (Choice of forum and jurisdiction) – the courts of Sweden
          shall have jurisdiction.</li></ol> <li><p><strong>Supplementary Terms to Standard Contractual Clauses</strong></p></li> <ol><li><p><strong>Documentation and compliance.</strong> For the purposes of Clauses
            8.9(b) and 8.9(e) the review and audit provisions in the Agreement and
            DPA shall apply.</p></li> <li><p><strong>Notification and Transparency.</strong></p> <ol type="a"><li><p>The Parties acknowledge and agree that Modal, where required by
                the Standard Contractual Clauses to notify the competent
                supervisory authority, shall first provide Customer with details
                of the notification, permitting Customer to have prior written
                input into the relevant notification where Customer so desires
                to do, and without delaying the timing of the notification
                unduly.</p></li> <li><p>For purposes of Clause 8.2 – Module 1, Clause 8.3 – Module 2 and
                Clause 15.1(a), the parties agree and acknowledge that it may
                not be possible for Modal to make the appropriate communications
                to data subjects and accordingly, Customer shall (following
                notification from Modal) have the option to be the party who
                communicates with the data subject, and Modal shall provide the
                level of assistance set out in the DPA.</p></li></ol></li> <li><p><strong>Signatories.</strong> Notwithstanding the fact that the SCCs
            are incorporated herein by reference without being signed directly, Modal
            and Customer each agrees that their execution of the Agreement is deemed
            to constitute its execution of the SCCs, and that it is duly authorized
            to do so on behalf of, and to contractually bind, the Data Exporter or
            Data Importer (as applicable) accordingly.</p></li></ol> <li><p><strong>Swiss Law Provisions</strong></p></li> <ol><li><p>Personal Data transfers from Switzerland will be governed by the
            SCCs as conformed to Swiss law as follows:</p> <ol type="a"><li>references to the EU, member states and GDPR in the SCCs are
              amended mutatis mutandis to refer to Switzerland, the Swiss
              Federal Data Protection Act, and the Swiss Federal Data Protection
              and Information Commissioner; and</li> <li>In Clause 17 (Governing Law) the laws of Switzerland shall govern,
              and in Clause 18 (Choice of forum and jurisdiction) the courts of
              Switzerland shall have jurisdiction.</li></ol></li></ol> <li><p><strong>United Kingdom Law Provisions</strong></p> <ol><li><p>Personal Data transfers from the United Kingdom will be governed
              by the SCCs as conformed to UK law pursuant to the International
              Data Transfer Addendum (the “IDTA”) issued by the UK Information
              Commissioner’s Office (the “ICO”) and laid before Parliament in
              accordance with s119A of the Data Protection Act 2018 on 2
              February 2022.</p></li> <li><p>In Part 1 of the IDTA, the information required by Tables 1 – 3 is
              provided in the Agreement, the DPA and these SCCs.</p></li> <li><p>The IDTA’s Mandatory Clauses are incorporated by reference into
              this DPA in accordance with Alternative Part 2 of the template
              IDTA.</p></li> <li><p>References to the EU, member states and GDPR in the Standard
              Contractual Clauses are amended mutatis mutandis to refer to the
              United Kingdom and UK GDPR.</p></li> <li><p>In Clause 17 of the Standard Contractual Clauses (Governing Law),
              the laws of England and Wales shall govern, and in Clause 18
              (Choice of forum and jurisdiction), the courts in London, England
              shall have jurisdiction. A data subject may also bring legal
              proceedings against the data exporter and/or data importer before
              the courts in the UK.</p></li></ol></li></ol> <h2>Schedule 1<br/>Description Of Data Processing</h2> <p>The data processing activities carried out by Modal under the Agreement
      may be described as follows:</p> <p><strong>Categories of data subjects whose personal data is transferred</strong></p> <ul style="list-style-type:none"><p>Data subjects are: (a) Customer’s personnel who use the Service by or at
        the direction of Customer, and (b) users of Customer’s product or
        service, if Customer imports their Personal Data into the Service.</p></ul> <p><strong>Categories of personal data transferred</strong></p> <ul style="list-style-type:none"><p>The categories of Personal Data are: (a) the name, email and telephone
        contact information for Customer personnel who use the Service, (b)
        other Personal Data that Customer or its users may process via the
        Service or otherwise provide to Modal, and (c) contact information for
        users of Customer’s product or service, if Customer stores such
        information and imports it into the Service.</p></ul> <p><strong>Sensitive data transferred</strong> (if applicable) and applied restrictions
      or safeguards that fully take into consideration the nature of the data and
      the risks involved, such as for instance strict purpose limitation, access
      restrictions (including access only for staff having followed specialised training),
      keeping a record of access to the data, restrictions for onward transfers or
      additional security measures.</p> <ul style="list-style-type:none"><p>N/A</p></ul> <p><strong>The frequency of the transfer (e.g. whether the data is transferred on
        a one-off or continuous basis).</strong></p> <ul style="list-style-type:none"><p>Continuous</p></ul> <p><strong>Nature of the processing</strong></p> <ul style="list-style-type:none"><p>Modal will process Personal Data to provide the Service identified in
        the Agreement.</p></ul> <p><strong>Purpose(s) of the data transfer and further processing</strong></p> <ul style="list-style-type:none"><p>Modal will transfer Personal Data to provide the Service identified in
        the Agreement.</p></ul> <p><strong>The period for which the personal data will be retained, or, if that is
        not possible, the criteria used to determine that period</strong></p> <ul style="list-style-type:none"><p>As described in the DPA</p></ul> <p><strong>For transfers to (sub-) processors, also specify subject matter, nature
        and duration of the processing</strong></p> <ul style="list-style-type:none"><p>The subprocessors referenced in the DPA provide portions of the platform
        used by Modal to provide the Service</p></ul> <h2>Schedule 2<br/>Technical and Organizational Measures (TOMs)</h2> <p>The technical and organizational measures (TOMs) provided below apply to
      Services provided by Modal Labs, Inc. except where Customer is responsible
      for its own TOMs in its use of the Services. Evidence of the
      implementations of these TOMs may be presented in the form of up-to-date
      attestations, reports or extracts from independent bodies upon written
      request from Customer.</p> <table><thead><tr><th>Technical and Organizational Security Measure</th><th>Details</th></tr></thead><tbody><tr><td>Measures of pseudonymisation and encryption of personal data</td><td>Customer data is stored in a multi-tenant application with logical
            separation between Customer instances. Sensitive authentication
            information is encrypted, and the database is encrypted at rest.</td></tr><tr><td>Measures for ensuring ongoing confidentiality, integrity,
            availability and resilience of processing systems and services</td><td>Modal has policies and procedures in place to ensure
            confidentiality, integrity and resilience of processing systems and
            services. These include an Access Control Policy, Business
            Continuity and Disaster Recovery Policy, Data Classification Policy
            and a Secure Development Policy.</td></tr><tr><td>Measures for ensuring the ability to restore the availability and
            access to personal data in a timely manner in the event of a
            physical or technical incident</td><td>Customer data is backed up at least at a daily cadence. Restoration
            tests are performed annually.</td></tr><tr><td>Processes for regularly testing, assessing and evaluating the
            effectiveness of technical and organizational measures in order to
            ensure the security of the processing</td><td>Modal monitors and tests controls to ensure they are operating as
            intended and updated as needed. Modal uses Vanta Inc. to automate
            several of these controls, including employee activity and adherence
            to Modal policies and procedures, infrastructure monitoring, and
            development procedures. Outside of this, Modal has completed its
            SOC2 Type II certification and maintains an active security program.</td></tr><tr><td>Measures for user identification and authorization</td><td>Modal maintains an Access Control Policy. Measures for access
            control and authorization include formally documented roles and
            permissions, encrypted connection to production systems and
            networks, and single-sign on or 2FA where available. Access reviews
            are performed on a regular basis.</td></tr><tr><td>Measures for the protection of data during transmission</td><td>All data transfer outside Modal’s private network is encrypted with
            HTTPS/SSL.</td></tr><tr><td>Measures for the protection of data during storage</td><td>Modal’s database and file stores are encrypted at rest.</td></tr><tr><td>Measures for ensuring physical security of locations at which
            personal data are processed</td><td>Modal does not operate physical servers or other infrastructure.
            For employer-provided computers: All Modal employees are required to
            complete physical security training, and all employees and
            contractors are required to enable a screen lock when the work
            computer is left unattended.</td></tr><tr><td>Measures for ensuring events logging</td><td>Modal has detailed event and data access logging, with automated
            alerts for anomalies or missing data.</td></tr><tr><td>Measures for ensuring system configuration, including default
            configuration</td><td>Modal maintains guidelines for configuring and hardening instances,
            images and containers before they can be used in production.</td></tr><tr><td>Measures for certification/assurance of processes and products</td><td>Modal has completed its SOC2 Type II certification, and engages a
            third-party to perform penetration tests on a regular basis.</td></tr><tr><td>Measures for ensuring data minimisation</td><td>Modal collects data in connection with Customer’s use of the
            Service, but only in aggregate, de-identified form which is not
            linked specifically to Customer or any individual, excluding
            Customer Data uploaded or submitted by Customer.</td></tr><tr><td>Measures for ensuring data quality</td><td>Changes to Modal data collection are reviewed, tested and monitored
            after deployment.</td></tr><tr><td>Measures for ensuring limited data retention</td><td>Modal retains data as long as the Modal has a need for its use, or
            to meet regulatory or contractual requirements. Once data is no
            longer needed, it is securely disposed of or archived.</td></tr><tr><td>Measures for ensuring accountability</td><td>Modal employees are required to review and acknowledge Modal
            security practices and policies, complete security training, and go
            through a security walkthrough with a senior member of the
            engineering organization. Modal conducts background checks on all
            new employees and requires all employees to sign a non-disclosure
            agreement before gaining access to systems.</td></tr><tr><td>Measures for allowing data portability and ensuring erasure</td><td>Customer may exercise portability or erasure rights upon request to
            Modal.</td></tr><tr><td>Technical and organizational measures of sub-processors</td><td>Modal collects and reviews the most security assessments from
            sub-processors on an annual basis.</td></tr></tbody></table> <h2>Schedule 3<br/>Subprocessor List</h2> <p>Identified at <a href="https://trust.modal.com/subprocessors">https://trust.modal.com/subprocessors</a></p></div></section>`);function c(e){n(e,s())}export{c as component,a as universal};
